-- Initial Hibernate 6.6 / PostgreSQL schema. No business data.
-- Existing databases require an explicitly reviewed baseline; never execute V1 over legacy tables.
create table "user_roles" ("user_id" uuid not null, roles integer);
create table movie (id uuid not null, created_at timestamp with time zone not null, description text not null, director varchar(150) not null, english_title varchar(150) not null, english_url_trailer text, imdb_id varchar(255) unique, original_title varchar(150), portuguese_title varchar(150) not null, portuguese_url_trailer text, release_date date, runtime integer, show_notes boolean, tmdb_id bigint unique, updated_at timestamp with time zone, url_image text, user_id uuid, primary key (id));
create table movie_discord (movie_id uuid not null, message_id varchar(255) unique, primary key (movie_id));
create table movie_genre (id bigint generated by default as identity, name varchar(255) not null unique, tmdb_id bigint unique, primary key (id));
create table movie_note (created_at timestamp with time zone not null, note integer, updated_at timestamp with time zone, movie_id uuid not null, user_id uuid not null, primary key (movie_id, user_id));
create table movie_wishlist (tmdb_id bigint not null, release_date date, title varchar(150), title_english varchar(150), url_image text not null, primary key (tmdb_id));
create table movie_wishlist_user_wishlist (wishlist_order integer, movie_id bigint not null, wishlist_id uuid not null, primary key (movie_id, wishlist_id));
create table movies_genres (genre_id bigint not null, movie_id uuid not null);
create table "user" (id uuid not null, created_at timestamp with time zone not null, email varchar(100) not null unique, name varchar(100) not null, password varchar(70) not null, redefine_password_key varchar(200), redefine_password_key_created_at timestamp with time zone, updated_at timestamp with time zone, primary key (id));
create table user_invites (id bigint generated by default as identity, code varchar(255) not null unique, primary key (id));
create table user_preferences (user_id uuid not null, notify boolean, primary key (user_id));
create table user_statistics (user_id uuid not null, consecutive_failed_login_attempts integer, last_login_at timestamp with time zone, primary key (user_id));
create table user_wishlist (id uuid not null, created_at timestamp with time zone not null, name varchar(30), shareable boolean not null, updated_at timestamp with time zone, user_id uuid, primary key (id), unique (user_id, name));
